list_inventory_locations.code:
var response = await client.InventoryLocations.ListInventoryLocationsAsync(
    new Dictionary<string, object?> { ["q"] = "Sydney" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var inventoryLocation in ((IReadOnlyList<object?>)body["inventory_locations"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{inventoryLocation["id"]} {inventoryLocation["name"]} {inventoryLocation["is_default"]}");

